public class Harness {
    static void check(int[] coinsArr, int total, Integer[] expected) {
        List<Integer> coins = new ArrayList<>();
        for (int c : coinsArr) coins.add(c);
        List<Integer> got = new ChangeCalculator(coins).computeMostEfficientChange(total);
