        String e = Arrays.toString(expected);
        System.out.println((g.equals(e) ? "OK   " : "FAIL ") + "coins=" + Arrays.toString(coinsArr)
                + " total=" + total + " got=" + g + " expected=" + e);
    }
    static void checkError(int[] coinsArr, int total, String msg) {
        List<Integer> coins = new ArrayList<>();
        for (int c : coinsArr) coins.add(c);
        try {
            new ChangeCalculator(coins).computeMostEfficientChange(total);
            System.out.println("FAIL no exception for " + total);
        } catch (IllegalArgumentException ex) {
            System.out.println((msg.equals(ex.getMessage()) ? "OK   " : "FAIL ") + "total=" + total
                    + " msg=" + ex.getMessage());
        }
    }
    public static void main(String[] args) {
        check(new int[]{1,5,10,25}, 1, new Integer[]{1});
        check(new int[]{1,5,10,25,100}, 25, new Integer[]{25});
        check(new int[]{1,5,10,25,100}, 15, new Integer[]{5,10});
